function checkerSummonCells(board, color2) {
  const rows = board.length, cols = board[0]?.length || 0;
  if (rows < 3 || cols < 4) return [];
  const row = color2 === "white" ? rows - 3 : 2;
  return [0, 1, cols - 2, cols - 1].map((col) => ({ row, col }));
}
