async function swapOnlineHostColor() {
  if (!canSwapOnlineRoomColors()) return;
  try {
    setOnlineBusy(true);
    const wasSpectator = online.role === "spectator";
    const service = getMultiplayerService();
    const previousColor = online.playerColor;
    const nextColor = previousColor === "black" ? "white" : "black";
    const nextSeatUser = nextColor === "white" ? online.whiteUser : online.blackUser;
    let room;
    if (wasSpectator) {
      room = await service.swapRoomPlayerColors({ shareId: online.roomShareId });
    } else if (nextSeatUser && nextSeatUser !== online.userId) {
      await service.changeRoomSeat({
        shareId: online.roomShareId,
        playerColor: null
      });
      try {
        await service.swapRoomPlayerColors({ shareId: online.roomShareId });
        room = await service.changeRoomSeat({
          shareId: online.roomShareId,
          playerColor: nextColor
        });
      } catch (error) {
        try {
          await service.changeRoomSeat({
            shareId: online.roomShareId,
            playerColor: previousColor
          });
        } catch {
        }
        throw error;
      }
    } else {
      room = await service.changeRoomSeat({
        shareId: online.roomShareId,
        playerColor: nextColor
      });
    }
    applyMultiplayerRoomSnapshot(room, { followRoom: true, loadSettings: false });
    getMultiplayerSession().setRoom(room, { followRoom: true });
    if (!wasSpectator && online.playerColor) {
      syncOnlineCampaignLobbyColor(online.playerColor);
      queueOnlineStateSave({ immediate: true });
    }
    toast(wasSpectator ? "흑백을 변경했습니다." : `${COLOR_LABELS[online.playerColor]}으로 변경했습니다.`);
  } catch (error) {
    toast(`흑백 변경 실패: ${error.message || error}`);
    await refreshMultiplayerRoom({ silent: true });
  } finally {
    setOnlineBusy(false);
    renderViewModeClasses();
    renderBoard();
    renderMeta();
    renderClockDisplays();
    renderOnlineStatus();
  }
}
