  if (state.mode === "idle") return "READY";
  if (state.mode === "auction") return "AUCTION";
  if (state.mode === "auction-placement") return "PLACE";
  if (state.mode === "draft") return state.draft.phase === "END" && usesMaterialRevelation(state) && state.revelation === true ? "FINALE" : state.draft.phase || "OPENING";
