    const infoSelected = cardVisible && mobileCardPreviewId === cardId;
    const helpSuppressed = cardVisible && cardHelpClickSuppressedIds.has(cardId);
    cardEl.classList.toggle("draft-preview", draftSelected);
    cardEl.classList.toggle("mobile-card-preview", infoSelected);
    cardEl.classList.toggle("card-help-click-suppressed", helpSuppressed);
