function isBloodVisualCard(card2) {
  return Boolean(card2?.effect === "bloodCard" || card2?.bloodStyle || card2?.librarySpecial === "blood-effect");
}
function captureHandScrollSnapshot(nextCards = []) {
  const hand = els.hand;
  if (!hand || hand.scrollWidth <= hand.clientWidth) return null;
  const previousIds = new Set(
    Array.from(hand.querySelectorAll(".card[data-card-id]")).map((cardEl) => cardEl.dataset.cardId).filter(Boolean)
  );
  if (!previousIds.size) return null;
  const sharesCard = (nextCards || []).some((card2) => card2?.instanceId && previousIds.has(card2.instanceId));
  if (!sharesCard) return null;
  return {
    left: hand.scrollLeft,
    top: hand.scrollTop
  };
}
function restoreHandScrollSnapshot(snapshot) {
  if (!snapshot) return;
  const restore = () => {
    const hand = els.hand;
    if (!hand) return;
    const maxLeft = Math.max(0, hand.scrollWidth - hand.clientWidth);
    hand.scrollLeft = Math.min(Math.max(0, Number(snapshot.left) || 0), maxLeft);
    hand.scrollTop = Math.max(0, Number(snapshot.top) || 0);
  };
  window.requestAnimationFrame(() => {
    restore();
    window.setTimeout(restore, 0);
  });
}
