      name: card2?.name || null,
      text: card2?.text || null,
      imageId: card2?.imageId || null,
      phase: card2?.phase || null,
      helpItems: card2?.helpItems || null,
      serverAuthoritativeCard: card2?.serverAuthoritativeCard === true,
      serverCardStatus: card2?.serverCardStatus || null,
      used: Boolean(card2?.used),
      passiveApplied: Boolean(card2?.passiveApplied),
      recovering: Boolean(card2?.recovering),
      nextTurnPending: Boolean(card2?.nextTurnPending),
      usesRemaining: Number(card2?.usesRemaining) || 0,
      emptySlot: Boolean(card2?.emptySlot),
      disabled: Boolean(card2?.disabled),
      spectatorColor: card2?.spectatorColor || null,
      bloodStyle: Boolean(card2?.bloodStyle),
