function syncRenderedQuickChessLobby({ searching, quickLibraryDisabled, statusText }) {
  const stage = els.multiplayerLobbyPanel?.querySelector(".quick-chess-stage");
  if (!stage) return false;
  const summary = stage.querySelector("[data-mp-quick-preference-summary]");
  const startButton = stage.querySelector(".quick-chess-start");
  const startLabel = startButton?.querySelector("span");
  const libraryButton = stage.querySelector("[data-mp-quick-notation-library]");
  if (!summary || !startButton || !startLabel || !libraryButton) return false;
  summary.textContent = multiplayerQuickPreferenceSummary();
  startLabel.textContent = statusText;
  startButton.classList.toggle("is-searching", searching);
  startButton.disabled = multiplayerMatchmakingBusy || multiplayerMatchmakingEntering;
  if (searching) {
    startButton.removeAttribute("data-mp-quick-start");
    startButton.setAttribute("data-mp-quick-cancel", "");
  } else {
    startButton.removeAttribute("data-mp-quick-cancel");
    startButton.setAttribute("data-mp-quick-start", "");
  }
  libraryButton.disabled = quickLibraryDisabled;
  return true;
}
