  state.deckSlots[campaignDeckColor] = timeTravelerCampaign ? timeTravelerDeck() : bloodMoonCampaign ? bloodMoonDeck() : knightJourneyCampaign ? knightJourneyHintDeck(campaign.setup) : [null, null, null];
