  state.replayEvents = [];
  state.replayEventNonce = 0;
  state.replayTailFrame = null;
  state.notationTimeline = [];
  state.replayTimelineReady = false;
  state.pendingNotations = [];
  state.pendingReplayVisuals = [];
  clearReplayFrameCache();
  state.historyViewIndex = null;
  state.actionsRemaining = currentActionLimit("white");
  if (singleCampaign) {
    state.clock = createClockState(null, null);
    state.draftClock = createSetupDraftClockState(state.clock, state);
  }
  const startsWithDraft = shotgunCampaign || blackTowerCampaign || configurableDraftCampaign && !state.draftDelete;
  const startsWithRuleEvent = configurableDraftCampaign && state.ruleOpeningEnabled;
  if (!singleCampaign && !auctionCampaign && !startsWithDraft && !startsWithRuleEvent) startClockForTurn("white");
  if (!shotgunCampaign && !startsWithRuleEvent) recordPosition();
  COLORS.forEach(queueInitialDeckGainNotations);
  recordBoardHistory(`campaign:${campaign.id}`);
